using System;
using System.Collections.Generic;
using System.Linq;
public sealed class SongesFight {public int floor;public long milliseconds;public string result="victoire";}
public sealed class SongesRoom {public int floor;public long milliseconds;}
public sealed class SongesState {public long totalMs,combatMs,roomMs;public List<SongesRoom> rooms=new List<SongesRoom>();public bool started,combat,paused,finished;public int floor;public List<SongesFight> fights=new List<SongesFight>();}
internal sealed class SongesRun {
 internal readonly SongesState State;long last=-1,startSeen=-1,endSeen=-1;int startHits,endHits,depthHits,candidateDepth=-1;bool resultLocked;
 internal SongesRun(SongesState state){State=state??new SongesState();if(State.fights==null)State.fights=new List<SongesFight>();if(State.rooms==null)State.rooms=new List<SongesRoom>();if(State.floor<0||State.floor>25||State.totalMs<0||State.combatMs<0||State.fights.Count>500||State.roomMs<0||State.rooms.Count>500||State.rooms.Any(r=>r==null||r.floor<0||r.floor>25||r.milliseconds<0)||State.fights.Any(f=>f==null||f.floor<0||f.floor>25||f.milliseconds<0))throw new System.IO.InvalidDataException("Chronomètre Songes invalide.");if(State.started&&!State.finished)State.paused=true;}
 internal void Tick(long now){if(last>=0&&now>=last&&State.started&&!State.paused&&!State.finished){long delta=now-last;State.totalMs+=delta;State.roomMs+=delta;if(State.combat)State.combatMs+=delta;}last=now;}
 internal void ResetDetection(){startHits=endHits=depthHits=0;startSeen=endSeen=-1;candidateDepth=-1;}
 internal void Resume(long now){Tick(now);State.paused=false;ResetDetection();}
 internal void Pause(long now){Tick(now);State.paused=!State.finished;ResetDetection();}
 internal void BeginFight(long now){Tick(now);if(State.finished||State.paused||State.combat)return;if(!State.started)State.started=true;State.combat=true;State.combatMs=0;}
 internal void EndFight(long now,bool victory){Tick(now);if(!State.combat||State.paused||State.finished)return;State.fights.Add(new SongesFight{floor=State.floor,milliseconds=State.combatMs,result=victory?"victoire":"défaite"});State.combat=false;State.combatMs=0;resultLocked=true;if(victory&&State.floor==25){State.finished=true;ArchiveRoom();}}
 internal void Finish(long now){Tick(now);if(!State.finished)ArchiveRoom();State.finished=true;State.paused=false;State.combat=false;}
 internal void Observe(long now,bool endTurn,bool victory,bool defeat,int? depth){Tick(now);if(State.paused||State.finished)return;if(depth.HasValue&&depth.Value>=0&&depth.Value<=25){if(candidateDepth==depth.Value)depthHits++;else{candidateDepth=depth.Value;depthHits=1;}if(depthHits>=2)SetFloor(now,depth.Value);}else{depthHits=0;candidateDepth=-1;}
 bool result=victory||defeat;if(!result){endHits=0;endSeen=-1;resultLocked=false;}if(endTurn&&!result&&!State.combat&&!resultLocked){if(startHits++==0)startSeen=now;if(startHits>=2){BeginFight(now);long lag=Math.Max(0,now-startSeen);if(State.totalMs==0){State.totalMs+=lag;State.roomMs+=lag;}State.combatMs=lag;startHits=0;}}else if(!endTurn){startHits=0;startSeen=-1;}
 if(result&&State.combat&&!resultLocked){if(endHits++==0)endSeen=now;if(endHits>=2){long lag=Math.Max(0,now-endSeen);State.combatMs=Math.Max(0,State.combatMs-lag);State.totalMs=Math.Max(0,State.totalMs-lag);if(victory&&State.floor==25)State.roomMs=Math.Max(0,State.roomMs-lag);EndFight(now,victory);if(!State.finished)State.totalMs+=lag;endHits=0;}}}
 void ArchiveRoom(){if(State.started&&State.roomMs>0)State.rooms.Add(new SongesRoom{floor=State.floor,milliseconds=State.roomMs});State.roomMs=0;}
 internal void SetFloor(long now,int floor){Tick(now);if(floor<0||floor>25||floor==State.floor)return;ArchiveRoom();State.floor=floor;}
 internal static string Duration(long ms){var t=TimeSpan.FromMilliseconds(Math.Max(0,ms));return ((int)t.TotalHours).ToString("00")+":"+t.Minutes.ToString("00")+":"+t.Seconds.ToString("00");}
 internal static void Test(){var r=new SongesRun(new SongesState());r.Resume(0);r.Observe(0,false,false,false,1);r.Observe(1000,true,false,false,1);if(r.State.combat)throw new Exception("Départ sans confirmation");r.Observe(2000,true,false,false,1);if(!r.State.combat||r.State.combatMs!=1000)throw new Exception("Départ combat");r.Observe(11000,false,true,false,1);r.Observe(12000,false,true,false,1);if(r.State.combat||r.State.fights.Count!=1||r.State.fights[0].milliseconds!=10000)throw new Exception("Arrêt sur victoire");r.Observe(13000,false,true,false,1);if(r.State.fights.Count!=1)throw new Exception("Victoire comptée deux fois");r.Observe(14000,false,false,false,4);r.Observe(15000,false,false,false,4);if(r.State.floor!=4||r.State.fights.Count!=1||r.State.rooms.Count!=1||r.State.rooms[0].floor!=1||r.State.rooms[0].milliseconds<=0)throw new Exception("Marché confondu avec combat");long before=r.State.totalMs;r.Observe(25000,false,false,false,6);r.Observe(26000,false,false,false,6);if(r.State.totalMs<=before||r.State.floor!=6||!r.State.rooms.Any(room=>room.floor==4&&room.milliseconds>0))throw new Exception("Chrono global salle bonus");r.Pause(27000);before=r.State.totalMs;r.Tick(37000);if(r.State.totalMs!=before)throw new Exception("Pause");r.Resume(38000);r.Observe(39000,true,false,false,25);r.Observe(40000,true,false,false,25);r.Observe(45000,false,true,false,25);r.Observe(46000,false,true,false,25);if(!r.State.finished||r.State.floor!=25||r.State.fights.Count!=2||r.State.rooms.Last().floor!=25||r.State.rooms.Sum(room=>room.milliseconds)!=r.State.totalMs)throw new Exception("Fin salle 25");}
}
